export enum PublishCalloutKind {
  /** No callout — no folder selected, or a request is in flight. */
  None = 'none',
  /** Informational callout describing who gets access once published. */
  Info = 'info',
  /** Warning callout — publishing will replace an existing version in this folder. */
  ReplaceWarning = 'replaceWarning',
  /** Error callout — the user lacks write access to the selected folder. */
  NoAccess = 'noAccess',
  /** Error callout — the most recent submit attempt failed. */
  SubmitError = 'submitError',
}

export enum PublicationRuleFunction {
  Equal = 'EQUAL',
  Contain = 'CONTAIN',
  Regex = 'REGEX',
}

export interface PublicationRule {
  /** Claim/category name this rule matches against, e.g. `'role'`. */
  source: string;
  /** Combining function applied across `targets`. */
  function: PublicationRuleFunction;
  /** Values combined with OR; exactly one pattern when `function` is `Regex`. */
  targets: string[];
}

export interface PublishDerivationInput {
  /** Whether a destination folder is currently selected. */
  hasSelectedFolder: boolean;
  /**
   * Whether the selected folder already has this publication — this exact
   * version, for a versioned catalog entity, or any prior publication at
   * all, for an unversioned resource (e.g. a conversation).
   */
  hasExistingPublicationInFolder: boolean;
  /** Whether the current user can publish to the selected folder. */
  hasWriteAccess: boolean;
  /** Whether a publish request is currently in flight. */
  isSubmitting: boolean;
  /** Whether the most recent submit attempt failed. */
  hasSubmitError: boolean;
  /**
   * Whether resubmitting when `hasExistingPublicationInFolder` is true is
   * allowed (catalog: republishing replaces the existing version) or
   * blocked entirely (conversations have no update/replace semantics —
   * publishing again to the same folder is not supported). Default `true`.
   */
  allowReplace?: boolean;
}

export interface PublishDerivedState {
  /** Which callout (if any) to show below the folder picker. */
  calloutKind: PublishCalloutKind;
  /** Whether the submit button is disabled. */
  isSubmitDisabled: boolean;
  /** Whether the submit button should show its loading/spinner state. */
  isSubmitLoading: boolean;
}

export interface PublishFolderNode {
  /** Full path segments to this folder, outermost first. Also serves as the unique key. */
  path: string[];
  /** Display name of this folder (its last path segment). */
  name: string;
  /** Child folders, if any. */
  children?: PublishFolderNode[];
}

export interface PublishHistoryEntry {
  /**
   * Semantic version string, e.g. "4.0.0". `undefined` for unversioned
   * resources (e.g. a conversation), where a folder having any entry at all
   * already means "already published here" — see `usePublishFlow`.
   */
  version?: string;
  /** Unix timestamp (ms) when this version was published. */
  publishedAt: number;
  /** Folder path segments this version was published to, outermost first. */
  folderPath: string[];
  /**
   * Whether this publication requested that the publisher's own credentials
   * for the resource be published alongside it. Reports what was requested,
   * never that the credential was applied. Absent reads the same as `false` —
   * a synthesised or unversioned entry may not know.
   */
  publishCredentials?: boolean;
}

export interface PublishResourceSummary {
  /** Display title/name shown in the summary row. */
  title: string;
  /** Version, when the resource is versioned. `undefined` for conversations. */
  version?: string;
  /** Entity category. When set, the summary row renders the entity header with icon and type label instead of the title-only row. */
  type?: CatalogEntityType;
  /** URL of the entity icon, used only by the entity-header row. */
  iconUrl?: string;
}

derivePublishState = (
  input: PublishDerivationInput,
): PublishDerivedState => {
  if (input.isSubmitting) {
    return {
      calloutKind: PublishCalloutKind.None,
      isSubmitDisabled: true,
      isSubmitLoading: true,
    };
  }

  if (!input.hasSelectedFolder) {
    return {
      calloutKind: PublishCalloutKind.None,
      isSubmitDisabled: true,
      isSubmitLoading: false,
    };
  }

  if (!input.hasWriteAccess) {
    return {
      calloutKind: PublishCalloutKind.NoAccess,
      isSubmitDisabled: true,
      isSubmitLoading: false,
    };
  }

  if (input.hasSubmitError) {
    return {
      calloutKind: PublishCalloutKind.SubmitError,
      isSubmitDisabled: false,
      isSubmitLoading: false,
    };
  }

  if (input.hasExistingPublicationInFolder) {
    return {
      calloutKind: PublishCalloutKind.ReplaceWarning,
      isSubmitDisabled: input.allowReplace === false,
      isSubmitLoading: false,
    };
  }

  return {
    calloutKind: PublishCalloutKind.Info,
    isSubmitDisabled: false,
    isSubmitLoading: false,
  };
}

formatPublishedDate = (
  publishedAt: number,
  now: number = Date.now(),
  locale?: string,
): string => {
  const daysElapsed = Math.floor((now - publishedAt) / DAY_MS);

  if (daysElapsed <= 0) {
    return 'Today';
  }
  if (daysElapsed === 1) {
    return 'Yesterday';
  }
  if (daysElapsed < 7) {
    return `${daysElapsed} days ago`;
  }

  return new Date(publishedAt).toLocaleDateString(locale, {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
  });
}

usePublishFlow = <
  TItem extends PublishFlowItem = PublishFlowItem,
>({
  item,
  history,
  folderItems: initialFolderItems,
  hasWriteAccess: resolveWriteAccess = () => true,
  defaultAuthor = '',
  onCreateFolder,
  onPublish,
  onPublishSuccess,
  onPublishError,
  onFetchExistingRules,
}: UsePublishFlowOptions<TItem>): UsePublishFlowResult => {
  const [folderItems, setFolderItems] = useState(initialFolderItems);
  useEffect(() => {
    setFolderItems(initialFolderItems);
  }, [initialFolderItems]);
  const [selectedFolderPath, setSelectedFolderPath] = useState<string[]>();
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [hasSubmitError, setHasSubmitError] = useState(false);
  const [rules, setRules] = useState<PublicationRule[]>([]);
  const [isRulesLoading, setIsRulesLoading] = useState(false);
  const [hasRulesLoadError, setHasRulesLoadError] = useState(false);
  const [author, setAuthorState] = useState(defaultAuthor);
  const [publishCredentials, setPublishCredentials] = useState(false);
  /*
   * Seeding `author` once would strand the field empty whenever the host's
   * display name resolves after the first render; syncing it on every
   * `defaultAuthor` change would wipe what the user typed. Tracking whether
   * the user has touched the field is what makes the sync one-way and
   * one-shot.
   */
  const [isAuthorEdited, setIsAuthorEdited] = useState(false);
  useEffect(() => {
    if (isAuthorEdited) {
      return;
    }
    setAuthorState(defaultAuthor);
  }, [defaultAuthor, isAuthorEdited]);

  const setAuthor = useCallback((next: string) => {
    setIsAuthorEdited(true);
    setAuthorState(next);
  }, []);

  useEffect(() => {
    if (selectedFolderPath == null) {
      setRules([]);
      setHasRulesLoadError(false);
      return;
    }
    if (!onFetchExistingRules) {
      return;
    }

    let isCancelled = false;
    setIsRulesLoading(true);
    setHasRulesLoadError(false);

    onFetchExistingRules(selectedFolderPath)
      .then((fetchedRules) => {
        if (isCancelled) return;
        setRules(fetchedRules);
      })
      .catch(() => {
        if (isCancelled) return;
        setHasRulesLoadError(true);
      })
      .finally(() => {
        if (isCancelled) return;
        setIsRulesLoading(false);
      });

    return () => {
      isCancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedFolderPath]);

  const hasExistingPublicationInFolder = useMemo(() => {
    if (!selectedFolderPath) {
      return false;
    }
    const key = selectedFolderPath.join('/');
    return history.some((entry) => {
      if (entry.folderPath.join('/') !== key) {
        return false;
      }
      return item.version == null ? true : entry.version === item.version;
    });
  }, [history, item.version, selectedFolderPath]);

  const handleCreateFolder = useCallback(
    async (parentPath: string[], name: string) => {
      setFolderItems((prev) => insertFolder(prev, parentPath, name));
      try {
        await onCreateFolder?.(parentPath, name);
      } catch {
        setFolderItems((prev) => removeFolder(prev, parentPath, name));
        setHasSubmitError(true);
      }
    },
    [onCreateFolder],
  );

  const handleSubmit = useCallback(async () => {
    if (!selectedFolderPath) {
      return false;
    }
    setIsSubmitting(true);
    setHasSubmitError(false);
    try {
      await onPublish(
        item,
        selectedFolderPath,
        rules,
        author.trim(),
        publishCredentials,
      );
      onPublishSuccess?.(item, selectedFolderPath);
      return true;
    } catch (error) {
      setHasSubmitError(true);
      onPublishError?.(item, selectedFolderPath, error);
      return false;
    } finally {
      setIsSubmitting(false);
    }
  }, [
    author,
    item,
    onPublish,
    onPublishError,
    onPublishSuccess,
    publishCredentials,
    rules,
    selectedFolderPath,
  ]);

  const reset = useCallback(() => {
    setFolderItems(initialFolderItems);
    setSelectedFolderPath(undefined);
    setHasSubmitError(false);
    setRules([]);
    setHasRulesLoadError(false);
    setAuthorState(defaultAuthor);
    setIsAuthorEdited(false);
    setPublishCredentials(false);
  }, [defaultAuthor, initialFolderItems]);

  return {
    folderItems,
    selectedFolderPath,
    setSelectedFolderPath,
    handleCreateFolder,
    hasExistingPublicationInFolder,
    hasWriteAccess: selectedFolderPath
      ? resolveWriteAccess(selectedFolderPath)
      : true,
    isSubmitting,
    hasSubmitError,
    handleSubmit,
    reset,
    rules,
    setRules,
    author,
    setAuthor,
    publishCredentials,
    setPublishCredentials,
    isRulesLoading,
    hasRulesLoadError,
  };
}

export interface PublishFlowItem {
  /** Version, when the item is versioned. `undefined` for unversioned resources. */
  version?: string;
}

export interface UsePublishFlowOptions<TItem extends PublishFlowItem> {
  /** The item being published — versioned, or an unversioned resource (e.g. a conversation). */
  item: TItem;
  /** Previously published entries for this item. */
  history: PublishHistoryEntry[];
  /** Root-level destination folder nodes, as currently known to the host. */
  folderItems: PublishFolderNode[];
  /**
   * Resolves whether the current user can publish to a given folder path.
   * Defaults to always allowing (`() => true`) when omitted.
   */
  hasWriteAccess?: (folderPath: string[]) => boolean;
  /**
   * Called when the user confirms a new folder name. The host owns
   * persisting the folder; the hook also adds it locally so it is
   * immediately selectable within this session. If the returned promise
   * rejects, the optimistically added folder is rolled back and the submit-
   * error callout is surfaced.
   */
  onCreateFolder?: (parentPath: string[], name: string) => void | Promise<void>;
  /**
   * Initial value for the publication's display author, and the value
   * `reset` restores.
   *
   * The hook cannot resolve this itself: who the signed-in user is, is host
   * knowledge, and this library holds no notion of a session. The host
   * passes its own resolved display name here. It may arrive after the first
   * render (a profile still loading) or change (a different session), which
   * is why {@link UsePublishFlowResult.author} re-syncs from it while the
   * user has not edited the field.
   *
   * Defaults to `''`, which leaves the decision entirely to the host's own
   * publish call.
   */
  defaultAuthor?: string;
  /**
   * Called with the destination folder path, current rules, trimmed display
   * author, and the credentials opt-in when the user confirms publish/update.
   *
   * `publishCredentials` is additive and positional: a host callback that
   * declares only the first four parameters stays assignable and keeps
   * behaving exactly as it did.
   */
  onPublish: (
    item: TItem,
    folderPath: string[],
    rules: PublicationRule[],
    author: string,
    publishCredentials: boolean,
  ) => Promise<void>;
  /** Called after a successful publish; the host surfaces its own success notification. */
  onPublishSuccess?: (item: TItem, folderPath: string[]) => void;
  /**
   * Called with the rejection reason when `onPublish` fails, before
   * `handleSubmit` resolves to `false`. The host surfaces its own error
   * notification; the hook only sets `hasSubmitError` for the inline callout.
   */
  onPublishError?: (item: TItem, folderPath: string[], error: unknown) => void;
  /**
   * Resolves the access rules already configured for a destination folder.
   * Called whenever `selectedFolderPath` changes to a defined folder; the
   * result fully replaces the current `rules` state (never merged). Omit to
   * skip pre-filling entirely — `rules` then only ever changes via
   * `setRules`.
   */
  onFetchExistingRules?: (folderPath: string[]) => Promise<PublicationRule[]>;
}

export interface UsePublishFlowResult {
  /** Folder tree, including any folders created (but not yet persisted) during this session. */
  folderItems: PublishFolderNode[];
  /**
   * Currently selected destination folder path. `undefined` means nothing
   * is selected; `[]` means the bucket root itself is selected (a distinct,
   * valid destination).
   */
  selectedFolderPath?: string[];
  /** Selects a destination folder or the root (`[]`); pass `undefined` to deselect. */
  setSelectedFolderPath: (path: string[] | undefined) => void;
  /** Confirms a new folder name: adds it locally and reports it to the host, rolling back and surfacing an error if the host rejects. */
  handleCreateFolder: (parentPath: string[], name: string) => Promise<void>;
  /**
   * Whether `selectedFolderPath` already has this publication — this exact
   * version, for a versioned item, or any prior entry at all, for an
   * unversioned item (whose `version` is `undefined`).
   */
  hasExistingPublicationInFolder: boolean;
  /** Whether the current user can publish to `selectedFolderPath`. */
  hasWriteAccess: boolean;
  /** Whether a publish request is currently in flight. */
  isSubmitting: boolean;
  /** Whether the most recent submit attempt failed. */
  hasSubmitError: boolean;
  /**
   * Submits the publish/update request for the selected folder. Resolves to
   * `true` on success and `false` if `onPublish` rejected, so the caller can
   * decide whether to close the flow.
   */
  handleSubmit: () => Promise<boolean>;
  /** Resets folder selection, any locally-created folders, rules, the credentials opt-in, and the submit error back to their initial state. */
  reset: () => void;
  /** Current access rules for the selected folder — fetched, manually edited, or both. */
  rules: PublicationRule[];
  /** Replaces the current rules; used by manual add/remove/clear actions. */
  setRules: (rules: PublicationRule[]) => void;
  /**
   * Current display author for the publication — the host-supplied
   * `defaultAuthor` until the user edits it.
   */
  author: string;
  /** Replaces the current display author; marks the field as user-edited, so `defaultAuthor` no longer overwrites it. */
  setAuthor: (author: string) => void;
  /**
   * Whether the publication should carry the publisher's own credentials for
   * the item. Starts `false` and is never derived from history, the selected
   * folder, or a previous publication — selecting it is always a deliberate
   * act, so a folder whose previous publication carried credentials still
   * opens with it cleared.
   */
  publishCredentials: boolean;
  /** Replaces the credentials opt-in. */
  setPublishCredentials: (value: boolean) => void;
  /** Whether `onFetchExistingRules` is currently resolving for the selected folder. */
  isRulesLoading: boolean;
  /** Whether the most recent `onFetchExistingRules` call failed. `rules` is left unchanged when this is `true`. */
  hasRulesLoadError: boolean;
}

filterFolderTree = (
  items: PublishFolderNode[],
  query: string,
): PublishFolderNode[] => {
  const trimmed = query.trim().toLowerCase();
  if (!trimmed) {
    return items;
  }

  return items.reduce<PublishFolderNode[]>((acc, node) => {
    const filteredChildren = node.children
      ? filterFolderTree(node.children, query)
      : undefined;
    const selfMatches = node.name.toLowerCase().includes(trimmed);

    if (selfMatches) {
      acc.push(node);
    } else if (filteredChildren?.length) {
      acc.push({ ...node, children: filteredChildren });
    }

    return acc;
  }, []);
}

getSiblingFolderNames = (
  items: PublishFolderNode[],
  parentPath: string[],
): string[] => {
  if (parentPath.length === 0) {
    return items.map((node) => node.name);
  }
  const parentKey = toFolderPathKey(parentPath);
  const findNode = (
    nodes: PublishFolderNode[],
  ): PublishFolderNode | undefined => {
    for (const node of nodes) {
      if (toFolderPathKey(node.path) === parentKey) {
        return node;
      }
      const found = node.children ? findNode(node.children) : undefined;
      if (found) {
        return found;
      }
    }
    return undefined;
  };
  return (findNode(items)?.children ?? []).map((node) => node.name);
}

getUniqueFolderName = (
  baseName: string,
  siblingNames: string[],
): string => {
  const lowerSiblingNames = new Set(
    siblingNames.map((name) => name.toLowerCase()),
  );
  if (!lowerSiblingNames.has(baseName.toLowerCase())) {
    return baseName;
  }
  let suffix = 2;
  while (lowerSiblingNames.has(`${baseName} ${suffix}`.toLowerCase())) {
    suffix += 1;
  }
  return `${baseName} ${suffix}`;
}

sortFolderTree = (
  items: PublishFolderNode[],
): PublishFolderNode[] =>
  [...items]
    .sort((a, b) => compareFolderNames(a.name, b.name))
    .map((node) =>
      node.children
        ? { ...node, children: sortFolderTree(node.children) }
        : node,
    )

toDialFileTree = (items: PublishFolderNode[]): DialFile[] =>
  items.map((node) => {
    const path = toFolderPathKey(node.path);
    return {
      path,
      name: node.name,
      folderId: path,
      nodeType: DialFileNodeType.FOLDER,
      items: node.children ? toDialFileTree(node.children) : undefined,
    };
  })

validateFolderName = (
  rawValue: string,
  siblingNames: string[],
  messages: FolderNameValidationMessages,
): string | null => {
  const trimmed = rawValue.trim();
  if (!trimmed) {
    return messages.empty;
  }
  if (trimmed.includes('..') || FORBIDDEN_FOLDER_NAME_CHARS_RE.test(trimmed)) {
    return messages.invalid;
  }
  if (
    siblingNames.some((name) => name.toLowerCase() === trimmed.toLowerCase())
  ) {
    return messages.duplicate;
  }
  return null;
}

export interface FolderNameValidationMessages {
  /** Shown when the trimmed name is empty. */
  empty: string;
  /** Shown when the name contains `..` or a forbidden character. */
  invalid: string;
  /** Shown when a sibling folder already has this name (case-insensitive). */
  duplicate: string;
}

PublishAccessRuleEditor: FC<PublishAccessRuleEditorProps> = ({
  sourceOptions,
  onSave,
  onCancel,
  disabled = false,
  maxTargets = MAX_TARGETS_DEFAULT,
  labels = {},
  errorClassName = 'dial-small-text',
  styles: stylesProp = {},
}) => {
  const cssVars = {
    ...buildCssVars({
      '--pare-mobile-bg': stylesProp.colors?.mobileBackground,
      '--pare-bg': stylesProp.colors?.background,
      '--pare-error-text': stylesProp.colors?.errorText,
      '--pare-select-border': stylesProp.colors?.selectBorder,
      '--pare-select-border-hover': stylesProp.colors?.selectBorderHover,
      '--pare-select-border-open': stylesProp.colors?.selectBorderOpen,
      '--pare-select-border-focus': stylesProp.colors?.selectBorderFocus,
    }),
    ...stylesProp.cssVars,
  };

  const {
    sourceLabel = 'Source',
    sourcePlaceholder = 'Select...',
    functionLabel = 'Function',
    equalOptionLabel = 'Equal',
    containOptionLabel = 'Contain',
    regexOptionLabel = 'Regex',
    targetsLabel = 'Targets',
    targetsPlaceholder = 'Add a target',
    targetsHintLabel = 'Press Enter or comma to add a target.',
    patternLabel = 'Pattern',
    patternPlaceholder = 'Enter a regular expression',
    invalidRegexError = 'Enter a valid regular expression.',
    requiredFieldError = 'This field is required.',
    targetsRequiredError = 'Add at least one target.',
    saveLabel = 'Save',
    cancelLabel = 'Cancel',
    dialogAriaLabel = 'Add access rule',
  } = labels;

  const patternErrorId = useId();
  const sourceElementId = useId();
  const functionElementId = useId();
  const targetsElementId = useId();
  const dialogRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    /*
     * Moves focus into the newly opened editor, matching the WAI-ARIA dialog
     * pattern; focus is restored to the trigger by the host on close.
     */
    dialogRef.current?.focus();
  }, []);

  const [source, setSource] = useState<string>();
  const [ruleFunction, setRuleFunction] = useState<PublicationRuleFunction>();
  const [targets, setTargets] = useState<string[]>([]);
  const [pattern, setPattern] = useState('');
  const [isSourceOpen, setIsSourceOpen] = useState(false);
  const [isFunctionOpen, setIsFunctionOpen] = useState(false);
  const [hasAttemptedSave, setHasAttemptedSave] = useState(false);

  /* Mirrors the Catalog "From" filter's default/focused/open border states
   * (see `libs/catalog/src/components/Filter/Filter.module.scss`) onto the
   * kit's own field styling; `:focus-within` in the module covers the
   * focused state via pure CSS. Picking a value closes the dropdown and
   * returns the field to its default border — there is no persistent
   * "has a value" state. */
  const sourceFieldClassName = mergeClasses(
    styles.selectField,
    isSourceOpen && styles.selectFieldOpen,
  );
  const functionFieldClassName = mergeClasses(
    styles.selectField,
    isFunctionOpen && styles.selectFieldOpen,
  );

  const sourceSelectOptions = useMemo(
    () => sourceOptions.map((option) => ({ value: option, label: option })),
    [sourceOptions],
  );

  const functionOptions = useMemo(
    () => [
      { value: PublicationRuleFunction.Equal, label: equalOptionLabel },
      { value: PublicationRuleFunction.Contain, label: containOptionLabel },
      { value: PublicationRuleFunction.Regex, label: regexOptionLabel },
    ],
    [equalOptionLabel, containOptionLabel, regexOptionLabel],
  );

  const isRegex = ruleFunction === PublicationRuleFunction.Regex;
  const isPatternValid = isValidRegex(pattern);

  const isStructurallyComplete =
    source != null &&
    ruleFunction != null &&
    (isRegex ? isPatternValid : targets.length > 0);

  const handleSourceChange = (next: string | string[]) => {
    setSource(Array.isArray(next) ? next[0] : next);
    setIsSourceOpen(false);
  };

  /*
   * EQUAL and CONTAIN both use the `TagInput` targets field, so switching
   * between them keeps whatever targets are already entered. Only crossing
   * the boundary to/from REGEX clears the fields, since that switches the
   * input type entirely (tags vs. a single pattern string).
   */
  const handleFunctionChange = (next: string | string[]) => {
    const value = Array.isArray(next) ? next[0] : next;
    const nextFunction = value as PublicationRuleFunction;
    const wasRegex = ruleFunction === PublicationRuleFunction.Regex;
    const willBeRegex = nextFunction === PublicationRuleFunction.Regex;
    if (wasRegex !== willBeRegex) {
      setTargets([]);
      setPattern('');
    }
    setRuleFunction(nextFunction);
    setIsFunctionOpen(false);
  };

  /** Trims each tag, rejects an exact-duplicate (post-trim, case-sensitive) target, and caps the list at `maxTargets`. `TagInput` is controlled, so the corrected list is what the field renders. */
  const handleTargetsChange = (nextTags: string[]) => {
    const deduped: string[] = [];
    for (const rawTag of nextTags) {
      const trimmed = rawTag.trim();
      if (trimmed.length === 0 || deduped.includes(trimmed)) {
        continue;
      }
      deduped.push(trimmed);
      if (deduped.length >= maxTargets) {
        break;
      }
    }
    setTargets(deduped);
  };

  const handleSave = () => {
    if (!isStructurallyComplete || source == null || ruleFunction == null) {
      setHasAttemptedSave(true);
      return;
    }
    onSave({
      source,
      function: ruleFunction,
      targets: isRegex ? [pattern.trim()] : targets,
    });
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key === 'Escape') {
      /*
       * Stops the keydown from reaching a host-level Escape listener (e.g.
       * the Publish panel's own close-on-Escape) so only this in-progress
       * rule is cancelled, not the whole panel.
       */
      event.stopPropagation();
      onCancel();
    }
  };

  return (
    // eslint-disable-next-line jsx-a11y/no-noninteractive-element-interactions
    <div
      ref={dialogRef}
      role="dialog"
      aria-modal="true"
      aria-label={dialogAriaLabel}
      tabIndex={-1}
      onKeyDown={handleKeyDown}
      style={cssVars}
      className={mergeClasses(
        'fixed inset-0 z-[60] flex flex-col gap-3 overflow-y-auto p-4',
        'desktop:static desktop:z-auto desktop:flex-none desktop:overflow-visible desktop:rounded-lg desktop:p-3',
        styles.dialog,
      )}
    >
      <Select
        id={sourceElementId}
        labelProps={{ label: sourceLabel }}
        options={sourceSelectOptions}
        value={source}
        onChange={handleSourceChange}
        placeholder={sourcePlaceholder}
        searchable={sourceOptions.length > SEARCHABLE_SOURCE_THRESHOLD}
        searchPlaceholder={sourcePlaceholder}
        disabled={disabled}
        open={isSourceOpen}
        onOpenChange={setIsSourceOpen}
        fieldClassName={sourceFieldClassName}
        invalid={hasAttemptedSave && source == null}
        error={
          hasAttemptedSave && source == null ? requiredFieldError : undefined
        }
      />

      <Select
        labelProps={{ label: functionLabel }}
        id={functionElementId}
        options={functionOptions}
        value={ruleFunction}
        onChange={handleFunctionChange}
        placeholder={functionLabel}
        disabled={disabled}
        open={isFunctionOpen}
        onOpenChange={setIsFunctionOpen}
        fieldClassName={functionFieldClassName}
        invalid={hasAttemptedSave && ruleFunction == null}
        error={
          hasAttemptedSave && ruleFunction == null
            ? requiredFieldError
            : undefined
        }
      />

      {isRegex ? (
        <div>
          <Input
            id={`${patternErrorId}-input`}
            labelProps={{ label: patternLabel }}
            placeholder={patternPlaceholder}
            value={pattern}
            onChange={(value) => setPattern(value ?? '')}
            invalid={
              (pattern.length > 0 || hasAttemptedSave) && !isPatternValid
            }
            aria-describedby={
              (pattern.length > 0 || hasAttemptedSave) && !isPatternValid
                ? patternErrorId
                : undefined
            }
            disabled={disabled}
          />
          {(pattern.length > 0 || hasAttemptedSave) && !isPatternValid && (
            <span
              id={patternErrorId}
              role="alert"
              className={mergeClasses(
                'mt-1 block',
                errorClassName,
                styles.error,
              )}
            >
              {invalidRegexError}
            </span>
          )}
        </div>
      ) : (
        <TagInput
          id={targetsElementId}
          labelProps={{ label: targetsLabel }}
          placeholder={targetsPlaceholder}
          caption={
            hasAttemptedSave && targets.length === 0
              ? undefined
              : targetsHintLabel
          }
          error={
            hasAttemptedSave && targets.length === 0
              ? targetsRequiredError
              : undefined
          }
          invalid={hasAttemptedSave && targets.length === 0}
          value={targets}
          onChange={handleTargetsChange}
          disabled={disabled}
          tagClassName={TAG_INPUT_TAG_CLASS_NAME}
        />
      )}

      {/*
       * `GhostButton` (Cancel) and `NeutralButton` (Save) stand in for
       * tertiary/secondary: the installed kit declares
       * `ButtonVariant.Tertiary`/`Secondary` but ships no CSS for them yet on
       * the real Button/GhostButton, so they would silently render as
       * primary-solid. Switch once the kit adds the styles.
       */}
      <div className="mt-auto flex justify-end gap-2 desktop:mt-2">
        <GhostButton
          label={cancelLabel}
          onClick={onCancel}
          disabled={disabled}
        />
        <NeutralButton
          label={saveLabel}
          onClick={handleSave}
          disabled={disabled}
        />
      </div>
    </div>
  );
}

