PublishFoldersTree: FC<PublishFoldersTreeProps> = ({
  items,
  selectedPath,
  onSelectedPathChange,
  onCreateFolder,
  searchQuery,
  disabled = false,
  createFolderLabel = 'Create new folder',
  cancelCreatingFolderLabel = 'Cancel',
  addSiblingFolderLabel = 'Add sibling',
  addChildFolderLabel = 'Add child',
  newFolderDefaultName = 'New folder',
  noResultsLabel = 'No folders match "{query}".',
  emptyFolderNameError = 'Folder name cannot be empty.',
  invalidFolderNameError = 'Folder name contains invalid characters.',
  duplicateFolderNameError = 'A folder with this name already exists.',
  rootLabel = 'Organization',
  expandedPaths: controlledExpandedPaths,
  onExpandedPathsChange,
  loadingPaths,
  styles: stylesProp = {},
}) => {
  const cssVars = {
    ...buildCssVars({
      '--pft-divider': stylesProp.colors?.divider,
    }),
    ...stylesProp.cssVars,
  };

  const [internalExpandedPaths, setInternalExpandedPaths] = useState<
    Set<string>
  >(
    () =>
      new Set(
        selectedPath?.map((_, i) =>
          toFolderPathKey(selectedPath.slice(0, i + 1)),
        ) ?? [],
      ),
  );
  const expandedPaths = controlledExpandedPaths ?? internalExpandedPaths;
  /*
   * The root node's own path key ('') is always kept expanded so its
   * children stay visible. It is stripped before the set reaches the host
   * because '' is not a real folder path the host can fetch children for.
   */
  const handleExpandedPathsChange = (next: Set<string>) => {
    const withoutRoot = new Set(next);
    withoutRoot.delete('');
    if (onExpandedPathsChange) {
      onExpandedPathsChange(withoutRoot);
    } else {
      setInternalExpandedPaths(withoutRoot);
    }
  };
  const [creatingParentPath, setCreatingParentPath] = useState<string[] | null>(
    null,
  );
  /* Resolved once per creation session to avoid an existing sibling name. */
  const [creatingFolderName, setCreatingFolderName] =
    useState(newFolderDefaultName);
  /*
   * The host `DialFoldersTree` component shows `onRenameValidate`'s result
   * inline but does not reliably block its own confirm callback on it (the
   * error can still be visible when the folder gets created — see #7968).
   * Track the last live-typed validation result ourselves so `handleConfirmCreatingFolder`
   * can refuse to create even when the value it receives no longer reflects
   * that error.
   */
  const lastLiveValidationErrorRef = useRef<string | null>(null);

  const trimmedQuery = searchQuery.trim();
  const isCreatingFolder = creatingParentPath != null;

  const matchingItems = useMemo(
    () => filterFolderTree(items, searchQuery),
    [items, searchQuery],
  );
  const hasNoSearchMatches =
    trimmedQuery.length > 0 && matchingItems.length === 0;
  /*
   * The filter is suspended while the inline create-folder row is open: the
   * row is rendered by `DialFoldersTree` underneath its parent node, so a
   * query that filters that parent out (a query matching nothing at all, in
   * particular) would otherwise hide the editor the user just opened.
   */
  const isFiltering = !isCreatingFolder && trimmedQuery.length > 0;

  const visibleItems = useMemo(
    () => sortFolderTree(isFiltering ? matchingItems : items),
    [isFiltering, matchingItems, items],
  );

  const searchExpandedPaths = useMemo(
    () => new Set(['', ...collectFolderKeys(visibleItems)]),
    [visibleItems],
  );
  const treeExpandedPaths = useMemo(
    () => new Set(['', ...(isFiltering ? searchExpandedPaths : expandedPaths)]),
    [isFiltering, searchExpandedPaths, expandedPaths],
  );

  const childFiles = useMemo<DialFile[]>(
    () => toDialFileTree(visibleItems),
    [visibleItems],
  );

  /**
   * The bucket root is a real, always-expanded top-level tree node (matching
   * the file manager's own root-node pattern) so it is selectable exactly
   * like any folder — `path: ''` maps to `selectedPath: []` via
   * `fromFolderPathKey`/`toFolderPathKey`. Omitted while a search matches
   * nothing so `emptyStateDescription` can render instead.
   */
  const dialFiles = useMemo<DialFile[]>(() => {
    if (isFiltering && childFiles.length === 0) {
      return [];
    }
    return [
      {
        path: '',
        name: rootLabel,
        folderId: '',
        nodeType: DialFileNodeType.FOLDER,
        items: childFiles,
      },
    ];
  }, [childFiles, rootLabel, isFiltering]);

  const createdFolderPath = creatingParentPath
    ? toFolderPathKey(creatingParentPath)
    : null;

  const folderNameErrors = {
    empty: emptyFolderNameError,
    invalid: invalidFolderNameError,
    duplicate: duplicateFolderNameError,
  };

  /*
   * A query that matched no folder reads as "the folder I want doesn't exist
   * yet", so creating from that state pre-fills the editor with the query —
   * which also keeps the confirmed folder visible once the filter resumes.
   */
  const resolveNewFolderName = (parentPath: string[]): string => {
    const isQueryUsableAsName =
      hasNoSearchMatches &&
      validateFolderName(trimmedQuery, [], folderNameErrors) == null;
    return getUniqueFolderName(
      isQueryUsableAsName ? trimmedQuery : newFolderDefaultName,
      getSiblingFolderNames(items, parentPath),
    );
  };

  const beginCreatingFolder = (parentPath: string[]) => {
    setCreatingParentPath(parentPath);
    setCreatingFolderName(resolveNewFolderName(parentPath));
    lastLiveValidationErrorRef.current = null;
    const parentKey = toFolderPathKey(parentPath);
    if (parentKey) {
      handleExpandedPathsChange(new Set(expandedPaths).add(parentKey));
    }
  };

  const handleStartCreatingFolder = () =>
    beginCreatingFolder(selectedPath ?? []);

  /**
   * Per-row context menu, mirroring the file manager's "Add sibling" /
   * "Add child" folder-creation actions (see
   * `useFolderCreation`/`startTreeSiblingFolderCreation`/
   * `startTreeChildFolderCreation` in `@epam/ai-dial-react-file-manager`'s `FileManager`
   * — not exported from the package, so reimplemented here against the
   * public `getContextMenuItems` prop instead). "Add sibling" is omitted for
   * the root node, which has no parent to create a sibling under.
   */
  const getFolderContextMenuItems = (file: DialFile): DropdownItem[] => {
    const childPath = fromFolderPathKey(file.path);
    const items: DropdownItem[] = [
      {
        key: 'add-child',
        label: addChildFolderLabel,
        icon: (
          <IconFolderPlus
            size={DIAL_ICON_SIZE.SM}
            aria-hidden
            stroke={DIAL_KIT_ICON_STROKE}
          />
        ),
        onClick: () => beginCreatingFolder(childPath),
      },
    ];
    if (file.path !== '') {
      items.push({
        key: 'add-sibling',
        label: addSiblingFolderLabel,
        icon: (
          <IconPlus
            size={DIAL_ICON_SIZE.SM}
            aria-hidden
            stroke={DIAL_KIT_ICON_STROKE}
          />
        ),
        onClick: () => beginCreatingFolder(childPath.slice(0, -1)),
      });
    }
    return items;
  };

  const validateNewFolderName = (rawValue: string): string | null => {
    if (!creatingParentPath) {
      return null;
    }
    const error = validateFolderName(
      rawValue,
      getSiblingFolderNames(items, creatingParentPath),
      folderNameErrors,
    );
    lastLiveValidationErrorRef.current = error;
    return error;
  };

  const handleConfirmCreatingFolder = (rawValue: string) => {
    if (!creatingParentPath) {
      return;
    }
    const trimmed = rawValue.trim();
    const priorLiveError = lastLiveValidationErrorRef.current;
    const error = validateNewFolderName(rawValue) ?? priorLiveError;
    if (!error) {
      void onCreateFolder(creatingParentPath, trimmed);
      onSelectedPathChange([...creatingParentPath, trimmed]);
    }
    setCreatingParentPath(null);
  };

  const handleCancelCreatingFolder = () => setCreatingParentPath(null);

  const handleItemClick = (file: DialFile) => {
    const isSelected =
      selectedPath != null && toFolderPathKey(selectedPath) === file.path;
    onSelectedPathChange(isSelected ? undefined : fromFolderPathKey(file.path));
  };

  return (
    <div
      style={cssVars}
      className={mergeClasses(
        disabled && 'pointer-events-none opacity-60',
        stylesProp.className,
      )}
    >
      <div className={mergeClasses('w-full min-w-0 max-w-full', styles.tree)}>
        <DialFoldersTree
          items={dialFiles}
          showFiles={false}
          selectedPath={
            selectedPath != null ? toFolderPathKey(selectedPath) : undefined
          }
          expandedPaths={treeExpandedPaths}
          onExpandedPathsChange={handleExpandedPathsChange}
          loadingPaths={loadingPaths}
          onItemClick={handleItemClick}
          getContextMenuItems={getFolderContextMenuItems}
          createdFolderPath={createdFolderPath}
          newFolderDefaultName={creatingFolderName}
          onCreateFolderSave={handleConfirmCreatingFolder}
          onCreateFolderCancel={handleCancelCreatingFolder}
          onRenameValidate={(value) => validateNewFolderName(value)}
          emptyStateTitle={
            isFiltering
              ? noResultsLabel.replace('{query}', trimmedQuery)
              : undefined
          }
        />
      </div>

      <div className={mergeClasses('my-2 h-px', styles.divider)} aria-hidden />

      {/*
       * Plain `GhostButton` stands in for a tertiary button: the installed
       * kit declares `ButtonVariant.Tertiary` but ships no CSS for it yet on
       * the real Button/GhostButton, so it would silently render as
       * primary-solid. Switch to `variant={ButtonVariant.Tertiary}` once the
       * kit adds the style.
       */}
      <div className="mb-4 flex flex-wrap items-center gap-2">
        <GhostButton
          onClick={handleStartCreatingFolder}
          label={createFolderLabel}
          iconBefore={
            <IconPlus
              size={DIAL_ICON_SIZE.SM}
              aria-hidden
              stroke={DIAL_KIT_ICON_STROKE}
            />
          }
          disabled={disabled || isCreatingFolder}
        />
        {isCreatingFolder && (
          <GhostButton
            label={cancelCreatingFolderLabel}
            onClick={handleCancelCreatingFolder}
            disabled={disabled}
          />
        )}
      </div>
    </div>
  );
}

export interface PublishFoldersTreeColors {
  /** Divider color above the folder-creation controls. Defaults to `--stroke-tertiary`. */
  divider?: string;
}

export interface PublishFoldersTreeProps {
  /** Root-level folder nodes. */
  items: PublishFolderNode[];
  /** Currently selected destination path; `undefined` means no selection and `[]` means the bucket root. */
  selectedPath?: string[];
  /** Called when the selected destination changes. */
  onSelectedPathChange: (path: string[] | undefined) => void;
  /** Called when a new folder name is confirmed. */
  onCreateFolder: (parentPath: string[], name: string) => Promise<void>;
  /** Host-owned search query used to filter the tree. */
  searchQuery: string;
  /** Disables every control. Defaults to `false`. */
  disabled?: boolean;
  /** Label for the folder-creation trigger. Defaults to `'Create new folder'`. */
  createFolderLabel?: string;
  /** Label for the action that cancels folder creation. Defaults to `'Cancel'`. */
  cancelCreatingFolderLabel?: string;
  /** Label for the context-menu action that creates a sibling folder. Defaults to `'Add sibling'`. */
  addSiblingFolderLabel?: string;
  /** Label for the context-menu action that creates a child folder. Defaults to `'Add child'`. */
  addChildFolderLabel?: string;
  /** Initial folder name unless a valid unmatched search query is available. Defaults to `'New folder'`. */
  newFolderDefaultName?: string;
  /** Empty-state message with a `{query}` placeholder. Defaults to `'No folders match "{query}".'`. */
  noResultsLabel?: string;
  /** Validation message for an empty folder name. Defaults to `'Folder name cannot be empty.'`. */
  emptyFolderNameError?: string;
  /** Validation message for a forbidden folder name. Defaults to `'Folder name contains invalid characters.'`. */
  invalidFolderNameError?: string;
  /** Validation message for a duplicate folder name. Defaults to `'A folder with this name already exists.'`. */
  duplicateFolderNameError?: string;
  /** Label for the selectable bucket root. Defaults to `'Organization'`. */
  rootLabel?: string;
  /** Externally controlled expanded folder path keys. */
  expandedPaths?: Set<string>;
  /** Called when expanded folder path keys change. */
  onExpandedPathsChange?: (paths: Set<string>) => void;
  /** Folder path keys currently being fetched by the host. */
  loadingPaths?: Set<string>;
  /** Style overrides. */
  styles?: PublishFoldersTreeStyles;
}

export interface PublishFoldersTreeStyles {
  /** Color overrides. */
  colors?: PublishFoldersTreeColors;
  /** Additional class name applied to the component root. */
  className?: string;
  /** Additional CSS custom properties applied to the component root. */
  cssVars?: CSSProperties;
}

PublishPanel: FC<PublishPanelProps> = ({
  resource,
  renderSummary,
  // TODO: will implement later — history, isHistoryLoading, hasHistoryError
  // are unused while the versions history section below is commented out.
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  history,
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  isHistoryLoading = false,
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  hasHistoryError = false,
  folderItems,
  selectedFolderPath,
  onSelectedFolderPathChange,
  onCreateFolder,
  expandedPaths,
  onExpandedPathsChange,
  loadingPaths,
  hasExistingPublicationInFolder,
  hasWriteAccess,
  isSubmitting,
  hasSubmitError = false,
  allowReplace = true,
  author,
  onAuthorChange,
  publishCredentials = false,
  onPublishCredentialsChange,
  rules,
  onRulesChange,
  ruleSourceOptions,
  isRulesLoading = false,
  hasRulesLoadError = false,
  labels = {},
  summaryTitleClassName = 'dial-body-semi-text',
  headingClassName = 'dial-body-semi-text',
  styles: stylesProp = {},
}) => {
  const {
    colors,
    folderTree: folderTreeStyles,
    accessRules: accessRulesStyles,
  } = stylesProp;
  const cssVars = {
    ...buildCssVars({
      '--pp-summary-title-text': colors?.summaryTitleText,
      '--pp-heading-text': colors?.headingText,
    }),
    ...stylesProp.cssVars,
  };

  /* Border and background belong to `ResourceSummary`'s own row, so they are
     forwarded as colors instead of being set as vars on an ancestor. */
  const summaryColors = {
    border: colors?.summaryBorder,
    background: colors?.summaryBackground,
    versionTagBorder: colors?.summaryVersionTagBorder,
    versionTagBackground: colors?.summaryVersionTagBackground,
    versionTagText: colors?.summaryVersionTagText,
  };

  const {
    folderLabel = 'Publish to folder',
    // TODO: will implement later — historyLabel is unused while the versions
    // history section below is commented out.
    replaceWarning = 'Version {version} is already published in {folder}. Publishing will replace it.',
    noAccessError = "You don't have permission to publish to {folder}. Pick another, or ask an owner for access.",
    submitError = 'Publishing failed. Please try again.',
    folderEmptyStateLabel,
    addSiblingFolderLabel,
    addChildFolderLabel,
    cancelCreatingFolderLabel,
    createFolderEmptyNameError,
    createFolderInvalidNameError,
    createFolderDuplicateNameError,
    // TODO: will implement later — historyLoadingLabel, historyErrorLabel,
    // historySharedCredentialsLabel are unused while the versions history
    // section below is commented out.
    rootFolderLabel = 'Organization',
    summaryVersionLabel,
    accessRulesLabels,
    searchPlaceholder,
    clearSearchAriaLabel,
    authorLabel = 'Author',
    authorPlaceholder = 'Author name',
    authorHint = 'Shown as the publication’s author. Defaults to you — replace it to credit a team instead.',
    credentialsLabel = 'Publish with my credentials',
    credentialsHint = 'Members will use this without signing in themselves. Your credential itself is never shown to them.',
  } = labels;

  const [searchQuery, setSearchQuery] = useState('');
  /* The kit associates the field with its visible label through this id, so the label is real rather than an aria-label. */
  const authorFieldId = useId();

  const handleSearchChange = (value?: string) => {
    setSearchQuery(value ?? '');
  };

  const isFolderSelected = selectedFolderPath != null;

  const derived = useMemo(
    () =>
      derivePublishState({
        hasSelectedFolder: isFolderSelected,
        hasExistingPublicationInFolder,
        hasWriteAccess,
        isSubmitting,
        hasSubmitError,
        allowReplace,
      }),
    [
      isFolderSelected,
      hasExistingPublicationInFolder,
      hasWriteAccess,
      isSubmitting,
      hasSubmitError,
      allowReplace,
    ],
  );

  const folderName = isFolderSelected
    ? (selectedFolderPath[selectedFolderPath.length - 1] ?? rootFolderLabel)
    : '';

  // TODO: will implement later — re-enable along with the versions history
  // section below.
  // const folderHistory = useMemo(() => {
  //   if (!isFolderSelected) {
  //     return [];
  //   }
  //   const key = selectedFolderPath.join('/');
  //   return history.filter((entry) => entry.folderPath.join('/') === key);
  // }, [history, selectedFolderPath, isFolderSelected]);

  const defaultSummary = renderSummary ? (
    renderSummary()
  ) : (
    <span
      className={mergeClasses(
        'truncate',
        summaryTitleClassName,
        styles.summaryTitle,
      )}
    >
      {resource?.title}
    </span>
  );

  return (
    <div
      className={mergeClasses('flex flex-col gap-5', PUBLISH_PANEL_CLASS.panel)}
      style={cssVars}
    >
      {resource?.type != null ? (
        <ResourceSummary
          item={{
            type: resource.type,
            name: resource.title,
            version: resource.version ?? '',
            iconUrl: resource.iconUrl,
          }}
          versionLabel={summaryVersionLabel}
          colors={summaryColors}
        />
      ) : (
        <ResourceSummary colors={summaryColors}>
          {defaultSummary}
        </ResourceSummary>
      )}

      <div>
        <div
          className={mergeClasses(
            'mb-2',
            headingClassName,
            styles.sectionHeading,
          )}
        >
          {folderLabel}
        </div>
        <div role="search" className="mb-3">
          <Search
            value={searchQuery}
            onChange={handleSearchChange}
            placeholder={searchPlaceholder}
            clearLabel={clearSearchAriaLabel}
            aria-label={searchPlaceholder}
          />
        </div>
        <PublishFoldersTree
          items={folderItems}
          selectedPath={selectedFolderPath}
          onSelectedPathChange={onSelectedFolderPathChange}
          onCreateFolder={onCreateFolder}
          expandedPaths={expandedPaths}
          onExpandedPathsChange={onExpandedPathsChange}
          loadingPaths={loadingPaths}
          searchQuery={searchQuery}
          disabled={isSubmitting}
          noResultsLabel={folderEmptyStateLabel}
          addSiblingFolderLabel={addSiblingFolderLabel}
          addChildFolderLabel={addChildFolderLabel}
          cancelCreatingFolderLabel={cancelCreatingFolderLabel}
          emptyFolderNameError={createFolderEmptyNameError}
          invalidFolderNameError={createFolderInvalidNameError}
          duplicateFolderNameError={createFolderDuplicateNameError}
          rootLabel={rootFolderLabel}
          styles={folderTreeStyles}
        />
        {derived.calloutKind !== PublishCalloutKind.None &&
          derived.calloutKind !== PublishCalloutKind.Info && (
            <div className="mt-3">
              <Notification
                type={NotificationType.SectionMessage}
                variant={calloutVariant(derived.calloutKind)}
                message={calloutMessage(derived.calloutKind, {
                  replaceWarning,
                  noAccessError,
                  submitError,
                  folderName,
                  version: resource?.version,
                })}
              />
            </div>
          )}

        {/* Sits with the destination rather than in its own section: the
            folder and the author together say what this publication is, and
            the rules below say who may see it. An empty author is a valid
            state, so nothing here can block submit. */}
        <div className="mt-4">
          <Input
            id={authorFieldId}
            labelProps={{ label: authorLabel }}
            placeholder={authorPlaceholder}
            caption={authorHint}
            value={author}
            onChange={(value) => onAuthorChange(value ?? '')}
            maxLength={MAX_AUTHOR_LENGTH}
            disabled={isSubmitting}
          />
        </div>

        {/* The consequence of ticking this lives in the caption, not the
            label alone: the kit wires the caption as the control's accessible
            description, so nothing here hand-rolls `aria-describedby`. */}
        {onPublishCredentialsChange != null && (
          <div className="mt-4">
            <Checkbox
              labelProps={{ label: credentialsLabel }}
              caption={credentialsHint}
              isSelected={publishCredentials}
              onChange={onPublishCredentialsChange}
              disabled={isSubmitting}
            />
          </div>
        )}

        {/* Nested inside the destination-folder block, and tighter than the
            inter-section gap, so the rules read as scoped to the selection
            above rather than as an independent control. */}
        <div className="mt-4">
          <PublishAccessRules
            rules={rules}
            onRulesChange={onRulesChange}
            sourceOptions={ruleSourceOptions}
            folderName={isFolderSelected ? folderName : undefined}
            disabled={isSubmitting}
            isLoading={isRulesLoading}
            hasLoadError={hasRulesLoadError}
            labels={accessRulesLabels}
            styles={accessRulesStyles}
          />
        </div>
      </div>

      {/* TODO: will implement later — versions history section is disabled
          for now, keep the markup below for when it's re-enabled. */}
      {/* {isFolderSelected && resource?.version != null && (
        <div>
          <div
            className={mergeClasses(
              'mb-2',
              headingClassName,
              styles.sectionHeading,
            )}
          >
            {historyLabel}
          </div>
          <PublishHistoryList
            entries={folderHistory}
            isLoading={isHistoryLoading}
            hasError={hasHistoryError}
            currentVersion={resource.version}
            loadingLabel={historyLoadingLabel}
            errorLabel={historyErrorLabel}
            sharedCredentialsLabel={historySharedCredentialsLabel}
          />
        </div>
      )} */}
    </div>
  );
}

export interface PublishPanelProps {
  /**
   * Display metadata for the summary row and for version-derived behavior:
   * the replace-warning callout's version substitution, and whether the
   * publish-history section is shown at all (only when `version` is set).
   * A `type` renders the entity-header row; otherwise the row is title-only,
   * unless `renderSummary` replaces it.
   */
  resource?: PublishResourceSummary;
  /**
   * Renders a custom summary row in place of the default title-only row built
   * from `resource.title`. Ignored when `resource.type` is set. Pass
   * `resource` alongside this so version-derived behavior (callout, history
   * section) keeps working.
   */
  renderSummary?: () => ReactNode;
  /** Previously published entries for this item. */
  history: PublishHistoryEntry[];
  /** Whether `history` is currently being fetched. Default: `false`. */
  isHistoryLoading?: boolean;
  /** Whether the most recent history fetch failed. Default: `false`. */
  hasHistoryError?: boolean;
  /** Destination folders available for selection. */
  folderItems: PublishFolderNode[];
  /**
   * Currently selected destination folder path. `undefined` means nothing
   * is selected; `[]` means the bucket root itself is selected (a distinct,
   * valid destination).
   */
  selectedFolderPath?: string[];
  /** Called when the user selects a destination folder or the root; `undefined` when deselected. */
  onSelectedFolderPathChange: (path: string[] | undefined) => void;
  /** Called when the user confirms a new folder name. */
  onCreateFolder: (parentPath: string[], name: string) => Promise<void>;
  /**
   * Externally-controlled set of expanded folder path keys. Pass this
   * together with `onExpandedPathsChange` when the host lazily fetches a
   * folder's children on expand.
   */
  expandedPaths?: Set<string>;
  /** Called when the set of expanded folders changes; required to control `expandedPaths`. */
  onExpandedPathsChange?: (paths: Set<string>) => void;
  /** Folder path keys currently being fetched by the host. */
  loadingPaths?: Set<string>;
  /**
   * Whether `selectedFolderPath` already has this publication — this exact
   * version, for a versioned `resource`, or any prior entry at all, for an
   * unversioned one.
   */
  hasExistingPublicationInFolder: boolean;
  /** Whether the current user can publish to `selectedFolderPath`. */
  hasWriteAccess: boolean;
  /** Whether a publish request is currently in flight. */
  isSubmitting: boolean;
  /** Whether the most recent submit attempt failed. */
  hasSubmitError?: boolean;
  /**
   * Whether resubmitting when `hasExistingPublicationInFolder` is true is
   * allowed (catalog default) or blocked (conversations — see
   * `PublishDerivationInput.allowReplace`). Default `true`.
   */
  allowReplace?: boolean;
  /**
   * Display author recorded on the publication. An empty value is valid and
   * never blocks submission — the host decides what an unset author means.
   */
  author: string;
  /** Called with the next author value on every edit. */
  onAuthorChange: (author: string) => void;
  /**
   * Whether the publication should carry the publisher's own credentials.
   * Only rendered when `onPublishCredentialsChange` is supplied. Default:
   * `false`.
   */
  publishCredentials?: boolean;
  /**
   * Called with the next value when the credentials opt-in is toggled.
   * Supplying it is what renders the control at all — a host with no use for
   * it gets exactly the panel it had before. The panel holds no state of its
   * own for the value.
   */
  onPublishCredentialsChange?: (value: boolean) => void;
  /** Current access rules, combined with AND. */
  rules: PublicationRule[];
  /** Called with the full next rules array on add, remove, or clear. */
  onRulesChange: (rules: PublicationRule[]) => void;
  /** Options offered in the access-rules editor's source picker. */
  ruleSourceOptions: string[];
  /** Whether existing rules are currently being fetched for the selected folder. Default: `false`. */
  isRulesLoading?: boolean;
  /** Whether the most recent existing-rules fetch failed. Default: `false`. */
  hasRulesLoadError?: boolean;
  /** Text overrides for all user-visible strings. */
  labels?: PublishPanelLabels;
  /** Typography class for the default summary title (unused when `renderSummary` or `resource.type` is passed). Default: `'dial-body-semi-text'`. */
  summaryTitleClassName?: string;
  /** Typography class for the "Publish to folder" and "Versions history" section headings. Default: `'dial-body-semi-text'`. */
  headingClassName?: string;
  /** Style overrides. */
  styles?: PublishPanelStyles;
}

export interface PublishPanelLabels {
  /** Label above the destination folder picker. Default: `'Publish to folder'`. */
  folderLabel?: string;
  /** Placeholder for the folder search input. Default: `'Search folders'`. */
  searchPlaceholder?: string;
  /** Accessible label for the search input's clear button. Default: `'Clear search'`. */
  clearSearchAriaLabel?: string;
  /** Label for the display-author field. Default: `'Author'`. */
  authorLabel?: string;
  /** Placeholder for the display-author field. Default: `'Author name'`. */
  authorPlaceholder?: string;
  /** Helper text below the display-author field. Default explains the value is shown as the publication's author. */
  authorHint?: string;
  /** Label for the credentials opt-in. Default: `'Publish with my credentials'`. */
  credentialsLabel?: string;
  /** Caption below the credentials opt-in, stating what ticking it does. Default explains members will use the resource without authorising and that the credential itself is never shown to them. */
  credentialsHint?: string;
  /** Label above the publish history list. Default: `'Versions history'`. */
  historyLabel?: string;
  /** Warning callout body shown when the folder already has this version; `{version}` and `{folder}` are replaced, with the folder name rendered bold. */
  replaceWarning?: string;
  /** Error callout body shown when the user lacks write access; `{folder}` is replaced, with the folder name rendered bold. */
  noAccessError?: string;
  /** Error callout body shown when the most recent submit attempt failed. */
