PublishFooter: FC<PublishFooterProps> = ({
  version,
  hasExistingPublicationInFolder,
  isSubmitDisabled,
  isSubmitLoading,
  onCancel,
  onSubmit,
  labels = {},
  colors,
}) => {
  const cssVars = buildCssVars({
    '--pf-border': colors?.border,
  });

  const {
    cancelLabel = 'Cancel',
    publishDefaultLabel = 'Publish',
    updateLabel = 'Update version {version}',
    publishingInProgressLabel = 'Publishing…',
  } = labels;

  const submitLabel = (() => {
    if (isSubmitLoading) {
      return publishingInProgressLabel;
    }
    if (hasExistingPublicationInFolder && version != null) {
      return updateLabel.replace('{version}', version);
    }
    return publishDefaultLabel;
  })();

  return (
    <div
      style={cssVars}
      className={mergeClasses(
        'flex items-center justify-end gap-2 border-t px-3.5 py-4 rtl:flex-row-reverse rtl:justify-start',
        styles.footer,
      )}
    >
      <GhostButton
        label={cancelLabel}
        disabled={isSubmitLoading}
        onClick={onCancel}
      />
      <NeutralButton
        label={submitLabel}
        disabled={isSubmitDisabled}
        iconBefore={
          isSubmitLoading ? <Spinner size={DIAL_ICON_SIZE.SM} /> : undefined
        }
        onClick={onSubmit}
      />
    </div>
  );
}

export interface PublishFooterColors {
  /** Top border color. Fallback: `--stroke-tertiary`. */
  border?: string;
}

export interface PublishFooterProps {
  /** The version being published, substituted into the submit label. `undefined` for unversioned resources (e.g. a conversation) — the submit label then always reads `publishDefaultLabel`. */
  version?: string;
  /** Whether this publication already exists at the selected destination folder. */
  hasExistingPublicationInFolder: boolean;
  /** Whether the submit button should be disabled. */
  isSubmitDisabled: boolean;
  /** Whether the submit button should show its loading/spinner state. */
  isSubmitLoading: boolean;
  /** Called when the user cancels the publish flow. */
  onCancel: () => void;
  /** Called when the user confirms the publish/update action. */
  onSubmit: () => void;
  /** Text overrides for all user-visible strings. */
  labels?: PublishFooterLabels;
  /** Color overrides. */
  colors?: PublishFooterColors;
}

export interface PublishFooterLabels {
  /** Cancel button label. Default: `'Cancel'`. */
  cancelLabel?: string;
  /** Submit button label when publishing a new version. Default: `'Publish'`. */
  publishDefaultLabel?: string;
  /** Submit button label when replacing an existing version; `{version}` is replaced. */
  updateLabel?: string;
  /** Submit button label while the request is in flight. Default: `'Publishing…'`. */
  publishingInProgressLabel?: string;
}

StandalonePublishPanel: FC<StandalonePublishPanelProps> = ({
  isOpen,
  resource,
  renderSummary,
  history,
  isHistoryLoading = false,
  hasHistoryError = false,
  folderItems,
  selectedFolderPath,
  onSelectedFolderPathChange,
  onCreateFolder,
  expandedPaths,
  onExpandedPathsChange,
  loadingPaths,
  hasExistingPublicationInFolder,
  hasWriteAccess,
  isSubmitting,
  hasSubmitError = false,
  allowReplace = true,
  author,
  onAuthorChange,
  rules,
  onRulesChange,
  ruleSourceOptions,
  isRulesLoading = false,
  hasRulesLoadError = false,
  onClose,
  returnFocusRef,
  onSubmit,
  panelLabels,
  panelStyles,
  footerLabels,
  labels = {},
  titleClassName = 'dial-body-semi-text',
  colors,
}) => {
  const cssVars = buildCssVars({
    '--spp-backdrop-bg': colors?.backdropBackground,
    '--spp-panel-bg': colors?.panelBackground,
    '--spp-panel-border': colors?.panelBorder,
    '--spp-divider-border': colors?.dividerBorder,
    '--spp-scrollbar-thumb': colors?.scrollbarThumb,
    '--spp-title-text': colors?.titleText,
  });

  const panelRef = useRef<HTMLDivElement>(null);
  const {
    title = 'Publish',
    ariaLabel = 'Publish',
    closeAriaLabel = 'Close',
  } = labels;

  const derived = useMemo(
    () =>
      derivePublishState({
        hasSelectedFolder: selectedFolderPath != null,
        hasExistingPublicationInFolder,
        hasWriteAccess,
        isSubmitting,
        hasSubmitError,
        allowReplace,
      }),
    [
      selectedFolderPath,
      hasExistingPublicationInFolder,
      hasWriteAccess,
      isSubmitting,
      hasSubmitError,
      allowReplace,
    ],
  );

  useEffect(() => {
    if (!isOpen) return;

    const panel = panelRef.current;
    if (!panel) return;

    const focusPanel = () => panel.focus({ preventScroll: true });
    focusPanel();

    /*
     * The control that opens this panel is typically a floating-ui menu item,
     * and such a menu hands focus back to its own trigger from a microtask
     * queued while it unmounts — during the same commit that mounts this
     * panel, so it lands after the synchronous focus above. Guarding the first
     * frame pulls any such hand-back straight back into the panel. The guard
     * is torn down on the next frame so that popovers the panel itself renders
     * through a portal (folder row menus, the rule source picker) keep focus.
     */
    const handleFocusIn = (event: FocusEvent) => {
      if (!panel.contains(event.target as Node)) {
        focusPanel();
      }
    };
    document.addEventListener('focusin', handleFocusIn);
    const guardFrameId = requestAnimationFrame(() => {
      document.removeEventListener('focusin', handleFocusIn);
    });

    const returnFocusTarget = returnFocusRef?.current;

    return () => {
      cancelAnimationFrame(guardFrameId);
      document.removeEventListener('focusin', handleFocusIn);
      if (returnFocusTarget?.isConnected) {
        returnFocusTarget.focus({ preventScroll: true });
      }
    };
  }, [isOpen, returnFocusRef]);

  useEffect(() => {
    if (!isOpen) return;

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        onClose();
        return;
      }
      if (event.key !== 'Tab') return;

      const panel = panelRef.current;
      if (!panel) return;

      /*
       * Only wrap while focus is genuinely inside the panel. The panel renders
       * folder-row menus and the rule source picker through portals that live
       * outside this subtree; pulling focus back from those would make them
       * unusable by keyboard.
       */
      const active = document.activeElement;
      if (!(active instanceof HTMLElement) || !panel.contains(active)) return;

      const focusable = getFocusableElements(panel);
      if (focusable.length === 0) {
        /* Nothing to cycle through — hold focus on the dialog itself rather
         * than letting Tab walk out into the page behind the modal. */
        event.preventDefault();
        panel.focus({ preventScroll: true });
        return;
      }

      const first = focusable[0];
      const last = focusable[focusable.length - 1];

      if (event.shiftKey && active === first) {
        event.preventDefault();
        last.focus();
        return;
      }
      if (!event.shiftKey && active === last) {
        event.preventDefault();
        first.focus();
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => {
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [isOpen, onClose]);

  return (
    <>
      <div
        style={cssVars}
        className={mergeClasses(
          'fixed inset-0 z-[51] transition-opacity duration-300',
          styles.backdrop,
          isOpen ? 'opacity-100' : 'pointer-events-none opacity-0',
        )}
        onClick={onClose}
        aria-hidden="true"
      />

      <div
        ref={panelRef}
        role="dialog"
        aria-modal="true"
        aria-label={ariaLabel}
        aria-hidden={!isOpen}
        inert={!isOpen}
        tabIndex={-1}
        style={cssVars}
        className={mergeClasses(
          'fixed inset-y-0 end-0 z-[52] flex w-full flex-col overflow-hidden',
          'desktop:rounded-ts-xl desktop:rounded-bs-xl desktop:w-[540px] desktop:border-s',
          'transition-transform duration-300',
          styles.panel,
          isOpen ? 'translate-x-0' : 'translate-x-full rtl:-translate-x-full',
        )}
      >
        <div className="flex shrink-0 items-center gap-2 px-[22px] py-3">
          <div className="flex-1" />
          <span
            className={mergeClasses(
              'flex-1 text-center',
              titleClassName,
              styles.title,
            )}
          >
            {title}
          </span>
          <div className="flex flex-1 justify-end">
            <CloseButton
              onClose={onClose}
              ariaLabel={closeAriaLabel}
              disabled={isSubmitting}
            />
          </div>
        </div>

        <div className={mergeClasses('shrink-0', styles.divider)} />

        <div
          className={mergeClasses(
            'min-h-0 flex-1 overflow-y-auto',
            styles.content,
          )}
        >
          <div className="p-[22px]">
            <PublishPanel
              resource={resource}
              renderSummary={renderSummary}
              history={history}
              isHistoryLoading={isHistoryLoading}
              hasHistoryError={hasHistoryError}
              folderItems={folderItems}
              selectedFolderPath={selectedFolderPath}
              onSelectedFolderPathChange={onSelectedFolderPathChange}
              onCreateFolder={onCreateFolder}
              expandedPaths={expandedPaths}
              onExpandedPathsChange={onExpandedPathsChange}
              loadingPaths={loadingPaths}
              hasExistingPublicationInFolder={hasExistingPublicationInFolder}
              hasWriteAccess={hasWriteAccess}
              isSubmitting={isSubmitting}
              hasSubmitError={hasSubmitError}
              allowReplace={allowReplace}
              author={author}
              onAuthorChange={onAuthorChange}
              rules={rules}
              onRulesChange={onRulesChange}
              ruleSourceOptions={ruleSourceOptions}
              isRulesLoading={isRulesLoading}
              hasRulesLoadError={hasRulesLoadError}
              labels={panelLabels}
              styles={panelStyles}
            />
          </div>
        </div>

        <PublishFooter
          version={resource?.version}
          hasExistingPublicationInFolder={hasExistingPublicationInFolder}
          isSubmitDisabled={derived.isSubmitDisabled}
          isSubmitLoading={derived.isSubmitLoading}
          onCancel={onClose}
          onSubmit={onSubmit}
          labels={footerLabels}
        />
      </div>
    </>
  );
}

